export function getNexoraSignalsForSymbol(symbol: string) {
  return NEXORA_SIGNAL_LIBRARY_2000.filter((signal) => signal.symbol === symbol && signal.enabled);
}

export function getNexoraSignalsByGroup(group: string) {
  return NEXORA_SIGNAL_LIBRARY_2000.filter((signal) => signal.group === group && signal.enabled);
}

export function getNexoraBlockingSignals() {
  return NEXORA_SIGNAL_LIBRARY_2000.filter((signal) => signal.blocksTrade && signal.enabled);
}
